  let aside = 0.35 / (span * 2.0);
  let inward = vec2f(mask_at(mask_uv + vec2f(aside, 0.0)) - mask_at(mask_uv - vec2f(aside, 0.0)),
    mask_at(mask_uv + vec2f(0.0, aside)) - mask_at(mask_uv - vec2f(0.0, aside)));
